/* ═══ OCTA · octa-config.js · 1KB ═══ */
/* ══════════════════════════════════════════════════════════════
  ⚙️ OCTA CONFIG — المصدر الوحيد لكل رقم في المشروع
  ──────────────────────────────────────────────────────────────
  أي رقم بيتحسب أو بيتقارن لازم يكون هنا.
  عدّل هنا مرة واحدة → كل الموقع بيتحدث.
  (الأوزان دي نفسها اللي هننقلها للسيرفر بعد كده)
  ══════════════════════════════════════════════════════════════ */
const CFG = {

  /* ═══════════════════════════════════════════════════════════
  🐙 المحاور الـ8 — المصدر الواحد للحقيقة
  ═══════════════════════════════════════════════════════════
  7 محاور ليها وزن في المحرك الحقيقي (update_prices.py · AXIS_WEIGHTS)
  + المحور الثامن overall وهو الناتج مش مدخل.

  ⚠ الأوزان دي مقفولة عمداً — `_hide_recipe()` بيشيلها من الردود.
  ⚠ محورين ثابتين: news=45 و portfolio=70 → 14% من الوزن مافيش فيه فرق.
  ⚠ valuation بيتحسب ويتعرض بس مش في AXIS_WEIGHTS إطلاقاً.
  كل ما ما تظبطّه، المستخدم بيوزّع على 7 بس.
  ═══════════════════════════════════════════════════════════ */
  axisAr: {
  technical:  'الفني',
  fundamental:'الأساسي',
  liquidity:  'السيولة',
  news:  'الأخبار',
  sentiment:  'المعنويات',
  risk:  'المخاطر',
  portfolio:  'المحفظة',
  valuation:  'التقييم',  /* محسوب — يدخل في أوزان المستخدم بس مش في المحرك */
  overall:  'التوافق العام'
  },

  /* ⛔⛔⛔ ٢٠ أكتوبر ٢٠٢٦ — الأوزان اتشالت من الملف العام.
  ⛌ كانت مكتوبة هنا — وأي حد يفتح مصدر الصفحة يقراها.
  ⛌ `after_request` بيخفيها من ردود JSON بس الملفات الثابتة مش JSON،
  ⛌ فالإخفاء مكانش بيوصلها.
  ⛌ الحل: بتتطلب من /api/engine-weights بعد تسجيل الدخول
  ⛌ (محمي بـrequire_user) وبتتخزن هنا في نفس المكان عشان الكود
  ⛌ القديم ما يتغيرشش.
  ⛌ عايز تشوف الأوزان؟ ادخل بـocta — بتظهر في كارت القرار. */
  engineWeights: {},   /* يتملا بعد الدخول */

  /* ── أوزان التقييم (مجموع 100) — تُجلب بعد الدخول ── */
  weights: { us:{}, egx:{}, usScan:{}, intel:{} },

  /* ── العتبات (من هنا بتتحدد Decisions والألوان) ── */
  th: {
  buy:  65,  /* 65 وفوق  → تجميع / شراء  */
  hold:  50,  /* 50 – 64  → احتفظ  */
  safe:  65,  /* عتبة الأمان  */
  mid:  45,  /* عتبة المتوسط  */
  market: 40  /* تحت كده → السوق هابط  */
  },

  /* ── تسميات القراءة (مش توصية) ── */
  /* ❌ ممنوع: شراء / بيع / توصية / قرار
  ✅ المسموح: إشارة / قراءة / مستوى مراقبة
  السبب: الموقع بيقول "لا أوامر شراء أو بيع"، فلو ظاهر
  كلام زي كده يكون متناقض مع نفسه. */
  labels: {
  buy:  'إشارة إيجابية',
  hold: 'إشارة محايدة',
  sell: 'إشارة سلبية'
  },

  /* ── المخاطرة ── */
  risk: { noChaseAtr: 2 }  /* لا تتسرّب فوق السعر بـ 2× التقلّب */

  /* ══════════════════════════════════════════════════════════
  *  📊 عدد الأسهم — المصدر الوحيد
  *  ─────────────────────────────────────────────────────────
  *  الرقم دلوقتي مش مكتوب في الكود، بيتحسب من الداتا.
  *  لكن فيه نصوص مكتوبة بإيدها فيها 252 و 296 و 285 و 19
  *  في أماكن مختلفة. لو الرقم غيّر، النصوص دي هتتكذب.
  *
  * التقسيم: 296 = كل الأسهم المسجلة
  *  252 = منهم اللي ليهم سعر لحظي
  * فهنقول للمستخدم: "من 296 سهم، 252 منهم بسعر لحظي"
  *  وده مش تناقض — ده توضيح.
  * ══════════════════════════════════════════════════════════ */
  ,stock: {
  total:  296,  /* كل الأسهم المسجلة — بتيجي من /api/data_full المحمي */
  priced: 252,  /* منهم اللي عندهم سعر لحظي من TradingView */
  /* بيحسب النص أوتوماتيك عشان مايتكتبش الرقم بإيد مرتين */
  note: function () {
  return 'من ' + CFG.stock.total + ' سهم، ' +
  CFG.stock.priced + ' منهم بسعر لحظي';
  }
  }
};
/* ══════════════════════════════════════════════════════════════
  ⚖️ تحميل الأوزان من السيرفر (محمي)
  ──────────────────────────────────────────────────────────────
  ⛔⛔⛔ ٢٠ أكتوبر ٢٠٢٦
  ⛌ الأوزان كانت مكتوبة في هذا الملف — كان أي حد يقدر يقراها.
  ⛌ دلوقتي: /api/engine-weights محمي بـrequire_user،
  ⛌ وبنملا CFG.weights و CFG.engineWeights بعد الدخول.
  ⛌ فـ«ارفع على الدومين» مش لازم يتغيّر — الأوزان جاية من السيرفر.
  ══════════════════════════════════════════════════════════════ */
(function () {
  if (typeof window === 'undefined') return;
  var CFG = window.CFG;
  if (!CFG) return;

  function apply(d) {
    if (!d || !d.ok) return;
    if (d.engine && Object.keys(d.engine).length) CFG.engineWeights = d.engine;
    if (d.weights) {
      ['us','egx','usScan','intel'].forEach(function (k) {
        if (d.weights[k] && Object.keys(d.weights[k]).length) CFG.weights[k] = d.weights[k];
      });
    }
    /* 🎯 إعادة الرسم: الصفحات اللي اتحسبت بأوزان فاضية
       لازم تتحدّث بعد ما الأوزان توصل. */
    try { if (typeof window.octaWeightsReady === 'function') window.octaWeightsReady(); }
    catch (e) { }
    document.dispatchEvent(new CustomEvent('octa:weights'));
  }

  /* ⛔ بنجيبها مرتين: مرة عند.authed ومرة احتياطاً.
  ⛌ لو البوابة أسرع من تحميل السكربت، الـauthed ممكن يفوتنا. */
  function load() {
    if (window.OCTA_API === undefined) return;
    try {
      fetch(window.OCTA_API + '/api/engine-weights', { cache: 'no-store' })
      .then(function (r) { return r.ok ? r.json() : null; })
      .then(apply).catch(function () { });
    } catch (e) { }
  }

  document.addEventListener('octa:authed', function () { setTimeout(load, 60); });
  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', function () { setTimeout(load, 900); });
  else setTimeout(load, 500);
})();
